import{z as i,x as d,o as r,c as p,q as A,j as n,D as e,d as t,s as l,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"循环预测与预测器训练","description":"","frontmatter":{"title":"循环预测与预测器训练","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/loop-predictor.md","filePath":"cs/loop-predictor.md","lastUpdated":1791063341000}'),B={name:"cs/loop-predictor.md"};function c(C,E,N,m,h,T){const o=d("Mermaid");return r(),p("div",null,[E[2]||(E[2]=A('<h1 id="循环预测与预测器训练" tabindex="-1">循环预测与预测器训练 <a class="header-anchor" href="#循环预测与预测器训练" aria-label="Permalink to &quot;循环预测与预测器训练&quot;">​</a></h1><div class="epigraph"><p>循环分支在 $N-1$ 次时成功、最后一次失败：饱和计数器必在出循环时错一次；记下 $N$ 就能在第 $N$ 次故意猜失败。</p><footer>—— 据 Sherwood and Calder 等对循环终止预测的论述；Seznec 将循环器接入 TAGE 族 整理</footer></div><p><a href="/cs/indirect-branch-predict">上一课</a>处理多目标地址。循环结尾的条件分支目标通常是立即数，方向却呈「111…10」：gshare 与 TAGE 能记相关，但对规整的行程长度仍浪费表项，且出循环那一次几乎总误预测。本课不重做 ITT。缺口是<strong>专用循环计数器</strong>，以及预测器<strong>何时更新</strong>——推测中的训练会把表写坏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>for (i=0;i&lt;N;i++)</code> 的向后分支：两位计数器在稳定期几乎全对，但每次离开循环必错，再进入时可能再错一次才饱和。\\(N\\) 若在一段时间内不变，硬件可以学这个 \\(N\\)。缺口不是更长的 GHR，而是<strong>检测「同一 PC 连续成功 \\(k\\) 次后失败」并在第 \\(k\\) 次输出失败</strong>。</p><p>训练时机：若在推测路径上就把成功填进循环计数，误预测路径上的假循环会把 \\(N\\) 学成垃圾。与 <a href="/cs/gshare-predictor">gshare</a> 的 GHR 检查点是同一纪律，本课把它钉死在循环器上。</p><p><span class="marginnote">许多实现把循环预测器当作 TAGE 的提供旁路：检测到规则循环则覆盖几何表的输出。Intel 优化手册所称 loop detector 是同一直觉。</span></p><p><span class="marginnote">trip count（行程数）翻译一下：就是循环体实际转多少圈。<code>for (i=0;i&amp;lt;N;i++)</code> 的行程数是 \\(N\\)，其向后分支的方向规律是「前 \\(N-1\\) 次成立、第 \\(N\\) 次失败」——像敲门 \\(N-1\\) 次都有人应，第 \\(N\\) 次注定没人应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>循环表按 PC 索引：存当前行程计数、学到的行程 \\(N\\)、置信度。每次该分支成功则计数 +1；失败则把计数与 \\(N\\) 比较，相等则置信上升，否则重学 \\(N\\)。预测：若计数 +1 将达到 \\(N\\)，猜失败，否则成功。</p>',10)),(r(),n(s,null,{default:e(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E5%BE%AA%E7%8E%AF%E5%88%86%E6%94%AF%20PC%22%5D%20--%3E%20LP%5B%22%E8%A1%8C%E7%A8%8B%E8%AE%A1%E6%95%B0%20%2F%20%E5%AD%A6%E5%88%B0%E7%9A%84%20N%22%5D%0A%20%20LP%20--%3E%20PRED%5B%22%E8%AE%A1%E6%95%B0%E5%B0%86%E6%BB%A1%E5%88%99%E7%8C%9C%E9%80%80%E5%87%BA%22%5D%0A%20%20PRED%20--%3E%20RET%5B%22%E6%8F%90%E4%BA%A4%E5%90%8E%E6%89%8D%E5%86%99%20N%20%E4%B8%8E%E8%AE%A1%E6%95%B0%22%5D%0A%20%20SPEC%5B%22%E6%8E%A8%E6%B5%8B%E8%B7%AF%E5%BE%84%22%5D%20-.-%3E%7C%22%E4%B8%8D%E6%8F%90%E4%BA%A4%E5%88%99%E4%B8%A2%22%7C%20RET%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"与 TAGE/感知器竞赛：循环器置信高则采用，否则退回通用预测。",-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"数字实例：行程 \\(N=10\\) 的循环，两位饱和计数器出循环必错一次、再进入时往往再错一次才重新饱和——每两轮白错两次。循环器学到 \\(N=10\\) 后，这几次全部省下；短循环密集的代码上，这点差别在 CPI 上可以直接测出来。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"同一串方向「1111111110」，饱和计数器与循环计数器的答卷不同：前者靠惯性，出循环必翻车；后者记着行程长度，故意在最后一次猜失败。",-1)),(r(),n(s,null,{default:e(()=>[l(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAT%5B%22%E6%96%B9%E5%90%91%E4%B8%B2%201111111110%EF%BC%88N%3D10%EF%BC%89%22%5D%20--%3E%20SAT%5B%22%E4%B8%A4%E4%BD%8D%E9%A5%B1%E5%92%8C%E8%AE%A1%E6%95%B0%E5%99%A8%22%5D%0A%20%20SAT%20--%3E%20W1%5B%229%20%E6%AC%A1%E6%88%90%E5%8A%9F%E5%90%8E%E4%BF%A1%E5%BF%83%E5%B7%B2%E6%BB%A1%EF%BC%8C%E7%8C%9C%E6%88%90%E5%8A%9F%22%5D%0A%20%20W1%20--%3E%20E1%5B%22%E7%AC%AC%2010%20%E6%AC%A1%E5%BF%85%E9%94%99%E4%B8%80%E6%AC%A1%22%5D%0A%20%20PAT%20--%3E%20LOOP%5B%22%E5%BE%AA%E7%8E%AF%E5%99%A8%EF%BC%9A%E5%AD%A6%E5%88%B0%20N%3D10%22%5D%0A%20%20LOOP%20--%3E%20W2%5B%22%E8%AE%A1%E6%95%B0%E5%B0%86%E6%BB%A1%E6%97%B6%E6%95%85%E6%84%8F%E7%8C%9C%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20W2%20--%3E%20E2%5B%22%E5%87%BA%E5%BE%AA%E7%8E%AF%E9%82%A3%E4%B8%80%E6%AC%A1%E4%B9%9F%E5%8F%AF%E5%AF%B9%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p><span class="marginnote">训练纪律这一步如果做错了，后面整个预测器都会乱套：在推测（尚未确认会执行）的路径上提前学 \\(N\\)，一条误预测带出来的假循环就能把表污染成垃圾值。所以 GHR、\\(N\\)、权重这些状态的更新必须以提交为准、且可回滚。</span></p><p>CPI：出循环那一次从「必错」变成「可对」，对短循环、高分支密度的核可测。\\(N\\) 变化（数据相关的 trip count）时置信下降，自动让位给 TAGE。嵌套循环要多路或多 PC：内层 \\(N\\) 稳定、外层每次改内层起点，别名仍可能。</p><p>训练纪律推广到所有预测器：架构状态（GHR、\\(N\\)、权重、TAGE 分配）以提交为准；推测更新必须可回滚。这为下一课「推测执行与恢复」准备好：预测器是微结构状态，恢复算法必须把它算进去。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把循环展开后的多条分支合成一个计数器。也不把软件 profile 的 trip count 当成硬件 \\(N\\) 的替代——那是编译课。间接跳转的「循环」是目标序列，不是本课的 0/1 行程。</p><p>后课默认：规则 trip count 可走专用计数器；任何预测表的更新以可恢复为前提。窗口里已经按预测执行的指令，错了怎么扔，是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>循环器记下行程 \\(N\\)，把出循环那一次从必错变成可预测。</li><li>预测器训练以提交为准，推测更新要能回滚。</li><li>窗口内的指令如何按预测执行再冲刷，是下一课恢复。</li><li>出处：Sherwood and Calder；Seznec TAGE 族中的循环组件；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const D=i(B,[["render",c]]);export{u as __pageData,D as default};
